private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (bb.hasRemaining()) {
        byte b = bb.get();
        if ((b & 0x80) == 0) {
            // Single byte character
            sb.append((char) b);
            i++;
        } else if ((b & 0xE0) == 0xC0) {
            // Double byte character
            if (bb.remaining() < 1) {
                break;
            }
            byte b2 = bb.get();
            int v = ((b & 0x1F) << 6) | (b2 & 0x3F);
            sb.append((char) v);
            i += 2;
        } else if ((b & 0xF0) == 0xE0) {
            // Triple byte character
            if (bb.remaining() < 2) {
                break;
            }
            byte b2 = bb.get();
            byte b3 = bb.get();
            int v = ((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
            sb.append((char) v);
            i += 3;
        } else if ((b & 0xF8) == 0xF0) {
            // Quadruple byte character
            if (bb.remaining() < 3) {
                break;
            }
            byte b2 = bb.get();
            byte b3 = bb.get();
            byte b4 = bb.get();
            int v = ((b & 0x07) << 18) | ((b2 & 0x3F) << 12) | ((b3 & 0x3F) << 6) | (b4 & 0x3F);
            sb.append((char) v);
            i += 4;
        } else {
            // Invalid start byte
            break;
        }
    }
    return i;
}

