public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = str.length();
    int i = 0;
    while (i < len) {
        char c = str.charAt(i);
        if (c == '\\') {
            i++;
            if (i >= len) {
                break;
            }
            c = str.charAt(i);
            switch (c) {
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'u':
                    if (i + 4 < len) {
                        String unicode = str.substring(i + 1, i + 5);
                        sb.append((char) Integer.parseInt(unicode, 16));
                        i += 4;
                    } else {
                        sb.append(c);
                    }
                    break;
                default:
                    sb.append(c);
                    break;
            }
        } else {
            sb.append(c);
        }
        i++;
    }
    return sb.toString();
}

